// 타임라인 컴포넌트 - 일정 블록 표시 및 편집
import { useRef, useEffect, useState, useCallback, useMemo } from 'react';
import { getTimelineHours, timeToMinutes, minutesToTime, snapToStep } from '../utils/date';
import type { ScheduleEvent } from '../types';
import { generateId } from '../stores/db';
import './Timeline.css';

interface TimelineProps {
  date: string;
  events: ScheduleEvent[];
  onEventCreate: (event: ScheduleEvent) => void;
  onEventUpdate: (event: ScheduleEvent) => void;
  onEventDelete: (eventId: string) => void;
  onEventClick: (event: ScheduleEvent) => void;
}

const HOUR_HEIGHT = 60; // 1시간 = 60px
const TIME_STEP = 5; // 5분 단위

// 이벤트 레이아웃 정보
interface EventLayout {
  event: ScheduleEvent;
  column: number;      // 가로 위치 (0부터 시작)
  totalColumns: number; // 그룹 내 총 열 수
}

export default function Timeline({
  date,
  events,
  onEventCreate,
  onEventUpdate,
  onEventDelete,
  onEventClick,
}: TimelineProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const timelineRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [isResizing, setIsResizing] = useState(false);
  const [dragEvent, setDragEvent] = useState<ScheduleEvent | null>(null);
  const [dragOffset, setDragOffset] = useState(0);
  const [isCreating, setIsCreating] = useState(false);
  const [createStart, setCreateStart] = useState(0);
  const [createEnd, setCreateEnd] = useState(0);
  
  // 모바일 롱프레스 관련
  const longPressTimer = useRef<number | null>(null);
  const touchStartPos = useRef<{ x: number; y: number } | null>(null);
  const [isLongPressTriggered, setIsLongPressTriggered] = useState(false);

  const hours = getTimelineHours(); // [4,5,...,23,0,1,2,3]

  // 겹치는 이벤트 레이아웃 계산
  const eventLayouts = useMemo((): EventLayout[] => {
    if (events.length === 0) return [];

    // 이벤트를 시작 시간 순으로 정렬
    const sorted = [...events].sort((a, b) => {
      const aStart = timeToMinutes(a.start);
      const bStart = timeToMinutes(b.start);
      return aStart - bStart;
    });

    // 각 이벤트의 시작/끝 분 계산 (04:00 기준으로 조정)
    const getAdjustedMinutes = (timeStr: string): number => {
      let minutes = timeToMinutes(timeStr);
      // 04:00 기준으로 조정
      let adjusted = minutes - 4 * 60;
      if (adjusted < 0) adjusted += 24 * 60;
      return adjusted;
    };

    // 두 이벤트가 겹치는지 확인
    const eventsOverlap = (e1: ScheduleEvent, e2: ScheduleEvent): boolean => {
      const s1 = getAdjustedMinutes(e1.start);
      let e1End = getAdjustedMinutes(e1.end);
      if (e1End <= s1) e1End += 24 * 60; // 자정 넘어가는 경우
      
      const s2 = getAdjustedMinutes(e2.start);
      let e2End = getAdjustedMinutes(e2.end);
      if (e2End <= s2) e2End += 24 * 60;
      
      return s1 < e2End && e1End > s2;
    };

    // 결과 배열
    const layouts: EventLayout[] = [];
    
    // 각 이벤트에 대해 열(column) 할당
    for (const event of sorted) {
      // 이 이벤트와 겹치는 이전 이벤트들 찾기
      const overlappingLayouts = layouts.filter(layout => 
        eventsOverlap(layout.event, event)
      );
      
      // 사용 중인 열 번호들
      const usedColumns = new Set(overlappingLayouts.map(l => l.column));
      
      // 가장 작은 사용 가능한 열 찾기
      let column = 0;
      while (usedColumns.has(column)) {
        column++;
      }
      
      layouts.push({ event, column, totalColumns: 1 });
    }

    // 겹치는 그룹별로 totalColumns 업데이트
    for (const layout of layouts) {
      // 이 이벤트와 겹치는 모든 이벤트의 최대 column 찾기
      const overlappingLayouts = layouts.filter(l => 
        eventsOverlap(l.event, layout.event)
      );
      const maxColumn = Math.max(...overlappingLayouts.map(l => l.column));
      
      // 그룹 내 모든 이벤트의 totalColumns 업데이트
      for (const l of overlappingLayouts) {
        l.totalColumns = Math.max(l.totalColumns, maxColumn + 1);
      }
    }

    return layouts;
  }, [events]);

  // 시간을 Y 위치로 변환 (04:00 기준)
  const timeToY = useCallback((timeStr: string): number => {
    // 빈 문자열이나 유효하지 않은 형식 처리
    if (!timeStr || !timeStr.includes(':')) {
      return 0; // 기본값: 04:00 위치
    }
    const minutes = timeToMinutes(timeStr);
    if (isNaN(minutes)) {
      return 0;
    }
    // 04:00 = 0, 05:00 = 60, ..., 03:00 = 1380
    let adjustedMinutes = minutes - 4 * 60;
    if (adjustedMinutes < 0) {
      adjustedMinutes += 24 * 60;
    }
    return (adjustedMinutes / 60) * HOUR_HEIGHT;
  }, []);

  // Y 위치를 시간으로 변환
  const yToTime = (y: number): string => {
    const totalMinutes = (y / HOUR_HEIGHT) * 60;
    const snappedMinutes = snapToStep(totalMinutes, TIME_STEP);
    // 04:00 기준 복원
    let actualMinutes = snappedMinutes + 4 * 60;
    if (actualMinutes >= 24 * 60) {
      actualMinutes -= 24 * 60;
    }
    return minutesToTime(actualMinutes);
  };
  // yToTime is used in creating preview
  void yToTime;

  // 초기 스크롤 위치 설정 (04:00이 보이도록)
  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = 0;
    }
  }, [date]);

  // 마우스/터치 다운 - 새 이벤트 생성 시작
  const handleTimelineMouseDown = (e: React.MouseEvent) => {
    if (e.target !== timelineRef.current && !(e.target as HTMLElement).classList.contains('time-slot')) {
      return;
    }

    const rect = timelineRef.current?.getBoundingClientRect();
    if (!rect) return;

    const y = e.clientY - rect.top + (containerRef.current?.scrollTop || 0);
    const startMinutes = snapToStep((y / HOUR_HEIGHT) * 60, TIME_STEP);

    setIsCreating(true);
    setCreateStart(startMinutes);
    setCreateEnd(startMinutes + 30); // 기본 30분
  };

  // 터치 시작 - 롱프레스로 일정 생성 (스크롤과 구분)
  const handleTimelineTouchStart = (e: React.TouchEvent) => {
    const target = e.target as HTMLElement;
    if (target !== timelineRef.current && !target.classList.contains('time-slot')) {
      return;
    }

    const touch = e.touches[0];
    touchStartPos.current = { x: touch.clientX, y: touch.clientY };
    setIsLongPressTriggered(false);

    // 500ms 롱프레스 타이머 시작
    longPressTimer.current = window.setTimeout(() => {
      const rect = timelineRef.current?.getBoundingClientRect();
      if (!rect || !touchStartPos.current) return;

      const y = touchStartPos.current.y - rect.top + (containerRef.current?.scrollTop || 0);
      const startMinutes = snapToStep((y / HOUR_HEIGHT) * 60, TIME_STEP);

      setIsCreating(true);
      setCreateStart(startMinutes);
      setCreateEnd(startMinutes + 30);
      setIsLongPressTriggered(true);
      
      // 진동 피드백 (지원되는 경우)
      if (navigator.vibrate) {
        navigator.vibrate(50);
      }
    }, 500);
  };

  // 터치 이동 - 스크롤 중이면 롱프레스 취소
  const handleTimelineTouchMove = (e: React.TouchEvent) => {
    if (!touchStartPos.current) return;

    const touch = e.touches[0];
    const deltaX = Math.abs(touch.clientX - touchStartPos.current.x);
    const deltaY = Math.abs(touch.clientY - touchStartPos.current.y);

    // 10px 이상 움직이면 롱프레스 취소 (스크롤로 인식)
    if (deltaX > 10 || deltaY > 10) {
      if (longPressTimer.current) {
        clearTimeout(longPressTimer.current);
        longPressTimer.current = null;
      }
      // 아직 롱프레스가 트리거되지 않았으면 스크롤 허용
      if (!isLongPressTriggered) {
        setIsCreating(false);
      }
    }
  };

  // 터치 끝 - 롱프레스 타이머 정리
  const handleTimelineTouchEnd = () => {
    if (longPressTimer.current) {
      clearTimeout(longPressTimer.current);
      longPressTimer.current = null;
    }
    touchStartPos.current = null;
  };

  // 마우스 이동 - 생성 중 또는 드래그 중
  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (!timelineRef.current) return;

    const rect = timelineRef.current.getBoundingClientRect();
    const y = e.clientY - rect.top + (containerRef.current?.scrollTop || 0);
    const currentMinutes = snapToStep((y / HOUR_HEIGHT) * 60, TIME_STEP);

    if (isCreating) {
      setCreateEnd(Math.max(currentMinutes, createStart + TIME_STEP));
    } else if (isDragging && dragEvent) {
      const newStartMinutes = Math.max(0, currentMinutes - dragOffset);
      const duration = timeToMinutes(dragEvent.end) - timeToMinutes(dragEvent.start);
      
      // 04:00 기준으로 복원
      let actualStart = newStartMinutes + 4 * 60;
      if (actualStart >= 24 * 60) actualStart -= 24 * 60;
      
      let actualEnd = actualStart + duration;
      if (actualEnd >= 24 * 60) actualEnd -= 24 * 60;

      const updatedEvent = {
        ...dragEvent,
        start: minutesToTime(actualStart),
        end: minutesToTime(actualEnd),
        updatedAt: Date.now(),
      };
      onEventUpdate(updatedEvent);
    } else if (isResizing && dragEvent) {
      const newEndMinutes = Math.max(
        timeToMinutes(dragEvent.start) - 4 * 60 + TIME_STEP,
        currentMinutes
      );
      
      let actualEnd = newEndMinutes + 4 * 60;
      if (actualEnd >= 24 * 60) actualEnd -= 24 * 60;

      const updatedEvent = {
        ...dragEvent,
        end: minutesToTime(actualEnd),
        updatedAt: Date.now(),
      };
      onEventUpdate(updatedEvent);
    }
  }, [isCreating, isDragging, isResizing, dragEvent, dragOffset, createStart, onEventUpdate]);

  // 마우스 업 - 생성 완료 또는 드래그 종료
  const handleMouseUp = useCallback(() => {
    if (isCreating && createEnd > createStart) {
      // 04:00 기준으로 복원
      let actualStart = createStart + 4 * 60;
      if (actualStart >= 24 * 60) actualStart -= 24 * 60;
      
      let actualEnd = createEnd + 4 * 60;
      if (actualEnd >= 24 * 60) actualEnd -= 24 * 60;

      const newEvent: ScheduleEvent = {
        id: generateId(),
        date,
        start: minutesToTime(actualStart),
        end: minutesToTime(actualEnd),
        title: '',
        color: '#a5b4fc',
        note: '',
        status: 'planned',
        createdAt: Date.now(),
        updatedAt: Date.now(),
      };
      onEventCreate(newEvent);
    }

    setIsCreating(false);
    setIsDragging(false);
    setIsResizing(false);
    setDragEvent(null);
  }, [isCreating, createStart, createEnd, date, onEventCreate]);

  // 터치 이동 핸들러 (롱프레스 후 드래그로 시간 조절)
  const handleTouchMove = useCallback((e: TouchEvent) => {
    // 롱프레스가 트리거되지 않았으면 스크롤 허용
    if (!isLongPressTriggered || !isCreating) return;
    if (!timelineRef.current) return;

    e.preventDefault(); // 롱프레스 트리거 후에만 스크롤 방지
    
    const rect = timelineRef.current.getBoundingClientRect();
    const touch = e.touches[0];
    const y = touch.clientY - rect.top + (containerRef.current?.scrollTop || 0);
    const currentMinutes = snapToStep((y / HOUR_HEIGHT) * 60, TIME_STEP);

    setCreateEnd(Math.max(currentMinutes, createStart + TIME_STEP));
  }, [isCreating, isLongPressTriggered, createStart]);

  // 터치 종료 핸들러
  const handleTouchEnd = useCallback(() => {
    // 롱프레스 타이머 정리
    if (longPressTimer.current) {
      clearTimeout(longPressTimer.current);
      longPressTimer.current = null;
    }
    
    if (isCreating && isLongPressTriggered && createEnd > createStart) {
      let actualStart = createStart + 4 * 60;
      if (actualStart >= 24 * 60) actualStart -= 24 * 60;
      
      let actualEnd = createEnd + 4 * 60;
      if (actualEnd >= 24 * 60) actualEnd -= 24 * 60;

      const newEvent: ScheduleEvent = {
        id: generateId(),
        date,
        start: minutesToTime(actualStart),
        end: minutesToTime(actualEnd),
        title: '',
        color: '#a5b4fc',
        note: '',
        status: 'planned',
        createdAt: Date.now(),
        updatedAt: Date.now(),
      };
      onEventCreate(newEvent);
    }

    setIsCreating(false);
    setIsDragging(false);
    setIsResizing(false);
    setDragEvent(null);
    setIsLongPressTriggered(false);
    touchStartPos.current = null;
  }, [isCreating, isLongPressTriggered, createStart, createEnd, date, onEventCreate]);

  // 이벤트 리스너 등록
  useEffect(() => {
    if (isCreating || isDragging || isResizing) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      window.addEventListener('touchmove', handleTouchMove, { passive: false });
      window.addEventListener('touchend', handleTouchEnd);
      return () => {
        window.removeEventListener('mousemove', handleMouseMove);
        window.removeEventListener('mouseup', handleMouseUp);
        window.removeEventListener('touchmove', handleTouchMove);
        window.removeEventListener('touchend', handleTouchEnd);
      };
    }
  }, [isCreating, isDragging, isResizing, handleMouseMove, handleMouseUp, handleTouchMove, handleTouchEnd]);

  // 블록 드래그 시작
  const handleBlockMouseDown = (e: React.MouseEvent, event: ScheduleEvent) => {
    e.stopPropagation();
    
    const rect = timelineRef.current?.getBoundingClientRect();
    if (!rect) return;

    const y = e.clientY - rect.top + (containerRef.current?.scrollTop || 0);
    const eventStartY = timeToY(event.start);
    
    setDragOffset((y / HOUR_HEIGHT) * 60 - (eventStartY / HOUR_HEIGHT) * 60);
    setDragEvent(event);
    setIsDragging(true);
  };

  // 리사이즈 핸들 드래그 시작
  const handleResizeMouseDown = (e: React.MouseEvent, event: ScheduleEvent) => {
    e.stopPropagation();
    setDragEvent(event);
    setIsResizing(true);
  };

  // 블록 클릭 (상세 열기)
  const handleBlockClick = (_e: React.MouseEvent, event: ScheduleEvent) => {
    if (!isDragging && !isResizing) {
      onEventClick(event);
    }
  };

  // 블록 삭제 (키보드)
  const handleBlockKeyDown = (e: React.KeyboardEvent, event: ScheduleEvent) => {
    if (e.key === 'Delete' || e.key === 'Backspace') {
      e.preventDefault();
      onEventDelete(event.id);
    }
  };

  return (
    <div className="timeline-container" ref={containerRef}>
      <div 
        className="timeline-grid" 
        ref={timelineRef}
        onMouseDown={handleTimelineMouseDown}
        onTouchStart={handleTimelineTouchStart}
        onTouchMove={handleTimelineTouchMove}
        onTouchEnd={handleTimelineTouchEnd}
        style={{ height: 24 * HOUR_HEIGHT }}
      >
        {/* 시간 라인 */}
        {hours.map((hour, index) => {
          // AM/PM 형식으로 변환
          const isPM = hour >= 12;
          const displayHour = hour === 0 ? 12 : hour > 12 ? hour - 12 : hour;
          const ampm = isPM ? 'pm' : 'am';
          
          return (
            <div 
              key={`hour-${hour}-${index}`} 
              className="timeline-row"
              style={{ 
                top: index * HOUR_HEIGHT,
                height: HOUR_HEIGHT 
              }}
            >
              <span className="time-label">{displayHour} {ampm}</span>
              <div className="time-slot"></div>
            </div>
          );
        })}

        {/* 이벤트 블록 컨테이너 - 이벤트 영역 */}
        <div className="events-container">
          {eventLayouts.map(({ event, column, totalColumns }) => {
            // 종일/다일 이벤트 처리
            // 타임테이블: 당일 04:00 ~ 다음일 03:59 (23시간)
            // 현재 날짜의 타임테이블에서 표시할 범위 계산
            
            // 기본값 설정 (빈 문자열인 경우 대비)
            let displayStart = event.start || '04:00';
            let displayEnd = event.end || '05:00';
            
            // 유효한 시간 형식인지 확인
            const isValidTime = (t: string) => t && /^\d{2}:\d{2}$/.test(t);
            if (!isValidTime(displayStart)) displayStart = '04:00';
            if (!isValidTime(displayEnd)) displayEnd = '05:00';
            
            if (event.isAllDay) {
              // 종일 이벤트: 이벤트 기간 중 현재 타임테이블에 해당하는 부분만 표시
              // 타임테이블: 당일 04:00 ~ 다음일 03:59
              const prevDate = new Date(date);
              prevDate.setDate(prevDate.getDate() - 1);
              const prevDateStr = prevDate.toISOString().split('T')[0];
              
              const nextDate = new Date(date);
              nextDate.setDate(nextDate.getDate() + 1);
              const nextDateStr = nextDate.toISOString().split('T')[0];
              
              // ★ 다음 날 시작 이벤트 → 현재 타임테이블의 00:00~03:59 부분에 표시
              // 예: 8일 타임테이블에서 9일 시작 종일 이벤트
              if (event.date === nextDateStr) {
                displayStart = '00:00';
                displayEnd = '03:59';
              }
              // 이벤트가 전날에서 시작하면 (전날 타임테이블의 끝부분에서 이어지는 경우)
              else if (event.date === prevDateStr) {
                // 전날 시작 이벤트가 현재 날짜로 이어지는 경우
                // 현재 타임테이블에서 00:00 ~ 03:59 부분 표시
                displayStart = '00:00';
                displayEnd = '03:59';
              } else if (event.date === date) {
                // 오늘 시작하는 종일 이벤트
                // 04:00부터 시작 (타임테이블 시작점)
                displayStart = '04:00';
                // endDate가 오늘과 같거나 없으면 다음날 00:00까지 (= 자정)
                if (!event.endDate || event.endDate === date) {
                  displayEnd = '00:00'; // 자정 = 다음날로 이어짐
                } else {
                  // 여러 날에 걸친 경우, 오늘 타임테이블에서는 끝까지
                  displayEnd = '03:59'; // 다음날 03:59까지
                }
              } else if (event.endDate === date) {
                // 오늘 끝나는 다일 종일 이벤트
                // 04:00 ~ 24:00 (= 다음날 00:00) 까지만
                displayStart = '04:00';
                displayEnd = '00:00'; // 24:00 = 자정
              } else if (event.date < date && event.endDate && event.endDate > date) {
                // 중간 날짜 (온종일)
                displayStart = '04:00';
                displayEnd = '03:59';
              }
            }
            
            let top = timeToY(displayStart);
            let bottom = timeToY(displayEnd);
            let height = bottom - top;
            if (height <= 0) height += 24 * HOUR_HEIGHT; // 자정 넘어가는 경우

            // 타임테이블 범위 내로 클리핑 (0 ~ 23시간)
            const maxHeight = 23 * HOUR_HEIGHT;
            if (top < 0) {
              height += top;
              top = 0;
            }
            if (top + height > maxHeight) {
              height = maxHeight - top;
            }
            if (height <= 0) return null; // 표시할 부분이 없으면 스킵

            // 가로 위치와 너비 계산 (퍼센트 기반)
            const widthPercent = 100 / totalColumns;
            const leftPercent = column * widthPercent;

            // 열이 많을수록 더 작은 너비 사용 (최소 15%)
            const baseWidth = Math.max(100 / totalColumns, 15);
            const widthPercentAdjusted = totalColumns > 4 ? baseWidth : widthPercent;

            return (
              <div
                key={event.id}
                className={`event-block ${isDragging && dragEvent?.id === event.id ? 'dragging' : ''} ${event.isAllDay ? 'all-day' : ''}`}
                style={{
                  top: top,
                  height: Math.max(height, 24),
                  backgroundColor: event.color,
                  left: `${leftPercent}%`,
                  width: `calc(${widthPercentAdjusted}% - 2px)`,
                }}
                tabIndex={0}
                onClick={(e) => handleBlockClick(e, event)}
                onMouseDown={(e) => handleBlockMouseDown(e, event)}
                onKeyDown={(e) => handleBlockKeyDown(e, event)}
              >
                <span className="event-title">{event.title || '(제목 없음)'}</span>
                {height >= 50 && event.note && (
                  <span className="event-note">{event.note}</span>
                )}
                {!event.isAllDay && height >= 40 && (
                  <span className="event-time-display">{event.start} - {event.end}</span>
                )}
                {event.isAllDay && height >= 30 && (
                  <span className="event-time-display">종일</span>
                )}
                {!event.isAllDay && (
                  <div 
                    className="resize-handle"
                    onMouseDown={(e) => handleResizeMouseDown(e, event)}
                  />
                )}
              </div>
            );
          })}
        </div>

        {/* 생성 중인 블록 미리보기 */}
        {isCreating && (
          <div
            className="event-block creating"
            style={{
              top: (createStart / 60) * HOUR_HEIGHT,
              height: Math.max(((createEnd - createStart) / 60) * HOUR_HEIGHT, 24),
              backgroundColor: '#a5b4fc',
            }}
          >
            <span className="event-title">(새 일정)</span>
          </div>
        )}
      </div>
    </div>
  );
}
