// To-do 리스트 컴포넌트
import { useState, useRef, useEffect } from 'react';
import type { TodoItem } from '../types';
import './TodoList.css';

// 작업 todo를 표시하기 위한 타입
interface WorkTodoDisplay {
  id: string;
  content: string;
  is_done: boolean;
  status?: 'active' | 'done' | 'delayed' | 'cancelled';
}

interface TodoListProps {
  todos: TodoItem[];
  onTodoCreate: (title: string) => void;
  onTodoUpdate: (todo: TodoItem) => void;
  onTodoDelete: (todoId: string) => void;
  workTodos?: WorkTodoDisplay[];
  onWorkTodoStatusChange?: (todoId: string, status: string) => void;
  onWorkTodoDelete?: (todoId: string) => void;
}

type TodoStatus = 'active' | 'done' | 'delayed' | 'cancelled';

const STATUS_LABELS: Record<TodoStatus, string> = {
  active: '진행중',
  done: '완료',
  delayed: '연기',
  cancelled: '취소',
};

const STATUS_CYCLE: TodoStatus[] = ['active', 'done', 'delayed', 'cancelled'];

export default function TodoList({
  todos,
  onTodoCreate,
  onTodoUpdate,
  onTodoDelete,
  workTodos = [],
  onWorkTodoStatusChange,
  onWorkTodoDelete,
}: TodoListProps) {
  const [newTodoText, setNewTodoText] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingText, setEditingText] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);
  const editInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editingId && editInputRef.current) {
      editInputRef.current.focus();
      editInputRef.current.select();
    }
  }, [editingId]);

  const handleAddTodo = () => {
    if (newTodoText.trim()) {
      onTodoCreate(newTodoText.trim());
      setNewTodoText('');
      inputRef.current?.focus();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleAddTodo();
    }
  };

  const handleStatusClick = (todo: TodoItem) => {
    const currentIndex = STATUS_CYCLE.indexOf(todo.status as TodoStatus);
    const nextStatus = STATUS_CYCLE[(currentIndex + 1) % STATUS_CYCLE.length];
    onTodoUpdate({
      ...todo,
      status: nextStatus,
      updatedAt: Date.now(),
    });
  };

  const handleDoubleClick = (todo: TodoItem) => {
    setEditingId(todo.id);
    setEditingText(todo.title);
  };

  const handleEditSave = (todo: TodoItem) => {
    if (editingText.trim()) {
      onTodoUpdate({
        ...todo,
        title: editingText.trim(),
        updatedAt: Date.now(),
      });
    }
    setEditingId(null);
  };

  const handleEditKeyDown = (e: React.KeyboardEvent, todo: TodoItem) => {
    if (e.key === 'Enter') {
      handleEditSave(todo);
    } else if (e.key === 'Escape') {
      setEditingId(null);
    }
  };

  const handleDelete = (todoId: string) => {
    onTodoDelete(todoId);
  };

  return (
    <div className="todo-list-container">
      <ul className="todo-list">
        {todos.map(todo => (
          <li 
            key={todo.id} 
            className={`todo-item status-${todo.status}`}
          >
            <button 
              className="todo-status-btn"
              onClick={() => handleStatusClick(todo)}
              title={STATUS_LABELS[todo.status as TodoStatus]}
            >
              {todo.status === 'done' ? '✓' : 
               todo.status === 'delayed' ? '⏳' :
               todo.status === 'cancelled' ? '✕' : '○'}
            </button>
            
            {editingId === todo.id ? (
              <input
                ref={editInputRef}
                type="text"
                className="todo-edit-input"
                value={editingText}
                onChange={e => setEditingText(e.target.value)}
                onBlur={() => handleEditSave(todo)}
                onKeyDown={e => handleEditKeyDown(e, todo)}
              />
            ) : (
              <span 
                className="todo-title"
                onDoubleClick={() => handleDoubleClick(todo)}
              >
                {todo.title}
              </span>
            )}

            <button 
              className="todo-delete-btn"
              onClick={() => handleDelete(todo.id)}
              title="삭제"
            >
              ×
            </button>
          </li>
        ))}
        
        {/* 작업에서 온 투두 */}
        {workTodos.length > 0 && (
          <>
            <li className="work-todos-divider">
              <span className="divider-text">📋 작업</span>
            </li>
            {workTodos.map(todo => {
              const status = todo.status || (todo.is_done ? 'done' : 'active');
              const handleWorkStatusClick = () => {
                if (!onWorkTodoStatusChange) return;
                const currentIndex = STATUS_CYCLE.indexOf(status as TodoStatus);
                const nextStatus = STATUS_CYCLE[(currentIndex + 1) % STATUS_CYCLE.length];
                onWorkTodoStatusChange(todo.id, nextStatus);
              };
              
              return (
                <li 
                  key={todo.id} 
                  className={`todo-item work-todo status-${status}`}
                >
                  <button
                    className="todo-status-btn"
                    onClick={handleWorkStatusClick}
                    title={STATUS_LABELS[status as TodoStatus]}
                  >
                    {status === 'done' ? '✓' : 
                     status === 'delayed' ? '⏳' :
                     status === 'cancelled' ? '✕' : '○'}
                  </button>
                  <span className="todo-title">{todo.content}</span>
                  {onWorkTodoDelete && (
                    <button
                      className="todo-delete-btn"
                      onClick={() => onWorkTodoDelete(todo.id)}
                      title="삭제"
                    >
                      ×
                    </button>
                  )}
                </li>
              );
            })}
          </>
        )}
      </ul>

      <div className="todo-add-form">
        <input
          ref={inputRef}
          type="text"
          placeholder="할 일 추가..."
          value={newTodoText}
          onChange={e => setNewTodoText(e.target.value)}
          onKeyDown={handleKeyDown}
        />
        <button onClick={handleAddTodo}>+</button>
      </div>
    </div>
  );
}
